window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2424559e743fde1c"]={"versions": [{"id": "FIG-2424559e743fde1c", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung des Diagnose-Manifests der AUTOSAR Adaptive Platform. Das Diagramm spezifiziert die Vererbungshierarchie der Metaklasse <code>DiagnosticMultipleResourcePortMapping</code> innerhalb des Metamodells für Diagnose-Mappings.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt eine lineare Spezialisierungshierarchie (Generalisierung) folgender Entitäten:</p>\n<ul class=\"fig-list\"><li><code>ARElement</code>: Abstrakte Basisklasse aller erstklassigen AUTOSAR-Modellelemente.\n</li><li><code>DiagnosticCommonElement</code>: Spezialisiert <code>ARElement</code> (dargestellt als oberstes Element im Klassenkopf).\n</li><li><code>DiagnosticMapping</code>: Spezialisiert <code>DiagnosticCommonElement</code>.\n</li><li><code>DiagnosticSwMapping</code>: Spezialisiert <code>DiagnosticMapping</code>.\n</li><li><code>DiagnosticMultipleResourcePortMapping</code>: Spezialisiert <code>DiagnosticSwMapping</code>. Es definiert das Attribut:\n<ul class=\"fig-list\"><li><code>overrideId: PositiveInteger [0..1]</code>: Optionaler Bezeichner zur Übersteuerung der Ressourcen-Zuordnung.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Interaktionen oder Laufzeitsequenzen. Es definiert deklarative Manifest-Strukturen für die Konfiguration und Codegenerierung im Adaptive-Plattform-Entwicklungsprozess.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\"><code>DiagnosticMultipleResourcePortMapping</code> erbt sämtliche Attribute, Referenzen und semantische Eigenschaften von <code>DiagnosticSwMapping</code>, <code>DiagnosticMapping</code>, <code>DiagnosticCommonElement</code> und <code>ARElement</code> (darunter paketierbare Namensraum- und Identifikationseigenschaften). Das Attribut <code>overrideId</code> ist als positiver ganzzahliger Wert mit Multiplizität 0..1 modelliert und im Manifest optional anzugeben.</p>"}, {"id": "FIG-ec9c5110383c377f", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung des Diagnose-Manifests der AUTOSAR Adaptive Platform. Das Diagramm spezifiziert die Vererbungshierarchie der Metaklasse <code>DiagnosticMultipleResourcePortMapping</code> innerhalb des Metamodells für Diagnose-Mappings.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt eine lineare Spezialisierungshierarchie (Generalisierung) folgender Entitäten:</p>\n<ul class=\"fig-list\"><li><code>ARElement</code>: Abstrakte Basisklasse aller erstklassigen AUTOSAR-Modellelemente.\n</li><li><code>DiagnosticCommonElement</code>: Spezialisiert <code>ARElement</code> (dargestellt als oberstes Element im Klassenkopf).\n</li><li><code>DiagnosticMapping</code>: Spezialisiert <code>DiagnosticCommonElement</code>.\n</li><li><code>DiagnosticSwMapping</code>: Spezialisiert <code>DiagnosticMapping</code>.\n</li><li><code>DiagnosticMultipleResourcePortMapping</code>: Spezialisiert <code>DiagnosticSwMapping</code>. Es definiert das Attribut:\n<ul class=\"fig-list\"><li><code>overrideId: PositiveInteger [0..1]</code>: Optionaler Bezeichner zur Übersteuerung der Ressourcen-Zuordnung.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Interaktionen oder Laufzeitsequenzen. Es definiert deklarative Manifest-Strukturen für die Konfiguration und Codegenerierung im Adaptive-Plattform-Entwicklungsprozess.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\"><code>DiagnosticMultipleResourcePortMapping</code> erbt sämtliche Attribute, Referenzen und semantische Eigenschaften von <code>DiagnosticSwMapping</code>, <code>DiagnosticMapping</code>, <code>DiagnosticCommonElement</code> und <code>ARElement</code> (darunter paketierbare Namensraum- und Identifikationseigenschaften). Das Attribut <code>overrideId</code> ist als positiver ganzzahliger Wert mit Multiplizität 0..1 modelliert und im Manifest optional anzugeben.</p>"}, {"id": "FIG-407f3c6bed06b616", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung des Diagnose-Manifests der AUTOSAR Adaptive Platform. Das Diagramm spezifiziert die Vererbungshierarchie der Metaklasse <code>DiagnosticMultipleResourcePortMapping</code> innerhalb des Metamodells für Diagnose-Mappings.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt eine lineare Spezialisierungshierarchie folgender Entitäten:</p>\n<ul class=\"fig-list\"><li><code>DiagnosticCommonElement</code>: Oberste dargestellte Diagnose-Basisklasse (im Diagrammkopf über <code>DiagnosticMapping</code> platziert).\n</li><li><code>DiagnosticMapping</code>: Spezialisiert <code>DiagnosticCommonElement</code>.\n</li><li><code>DiagnosticSwMapping</code>: Spezialisiert <code>DiagnosticMapping</code>.\n</li><li><code>DiagnosticMultipleResourcePortMapping</code>: Spezialisiert <code>DiagnosticSwMapping</code>. Es besitzt das Attribut:\n<ul class=\"fig-list\"><li><code>overrideId: PositiveInteger [0..1]</code>: Optionaler Bezeichner zur Übersteuerung der Ressourcen-Zuordnung.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Interaktionen oder Laufzeitsequenzen. Es definiert deklarative Manifest-Strukturen für die Konfiguration und Codegenerierung im Adaptive-Plattform-Entwicklungsprozess.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\"><code>DiagnosticMultipleResourcePortMapping</code> erbt über <code>DiagnosticSwMapping</code> und <code>DiagnosticMapping</code> von <code>DiagnosticCommonElement</code>. Das optionale Attribut <code>overrideId</code> besitzt den Datentyp <code>PositiveInteger</code> mit der Kardinalität 0..1. Implementierungen und Generatoren werten die abgeleiteten Eigenschaften der dargestellten Vererbungskette für die Port-Mapping-Konfiguration aus.</p>"}], "trans": [{"from": "FIG-2424559e743fde1c", "to": "FIG-ec9c5110383c377f", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-ec9c5110383c377f", "to": "FIG-407f3c6bed06b616", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>ARElement</code>: Die oberste Generalisierungsklasse in der Vererbungshierarchie oberhalb von <code>DiagnosticCommonElement</code> entfällt im Klassendiagramm; die oberste gezeigte Klasse fasst nun <code>DiagnosticCommonElement</code> und <code>DiagnosticMapping</code> in einem gemeinsamen Kasten zusammen.\n</li></ul>"}]};
